#!/usr/bin/env bash
# Renders the live room's plate for the bar, for a wall of 5 boxes (production's, the default)
# or of 6 (the local wall with its test game):
#   landing/tools/blender/plate.sh [boxes]
# The base is rendered in two halves so that each job stays under ten minutes, then one pass
# per lamp, the surroundings for the pieces' shine, and the jukebox.
# About 45 minutes on this machine. Then: node lobby/tools/pack-baked.mjs [boxes]
# Do not edit this file while it runs: bash reads a script as it goes.
set -uo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
boxes="${1:-5}"
name="plate"; [ "$boxes" != "5" ] && name="plate$boxes"
run() { "$here/run.sh" "$@" 2>&1 | grep "saved\|rror"; }
run plate-juke - 96
run "$name-env" - 64
run "$name-base" - 64 0,0,0.5,1
run "$name-base" - 64 0.5,0,1,1
i=0
while [ "$i" -lt "$boxes" ]; do run "$name-lamp$i" - 64; i=$((i + 1)); done
echo done > "$here/out/.$name-done"
